<script setup lang="ts">import {ref,watch} from 'vue';interface Props{open?:boolean;title?:string;disabled?:boolean};const props=withDefaults(defineProps<Props>(),{open:false,disabled:false});const emit=defineEmits<{'update:open':[value:boolean];toggle:[value:boolean]}>();const details=ref<HTMLDetailsElement>();watch(()=>props.open,value=>{if(details.value)details.value.open=value});function onToggle(){const value=Boolean(details.value?.open);emit('update:open',value);emit('toggle',value)}</script>
<template><details ref="details" class="uv-accordion" :open="open" @toggle="onToggle"><summary class="uv-accordion__summary" :aria-disabled="disabled" @click="disabled&&$event.preventDefault()"><span><slot name="title">{{title}}</slot></span><span class="uv-accordion__chevron" aria-hidden="true">⌄</span></summary><div class="uv-accordion__content"><slot/></div></details></template>
<style>.uv-accordion{border:1px solid var(--uv-color-border,#dbe3ef);border-radius:var(--uv-radius-lg,.875rem);background:var(--uv-color-surface,#fff);color:var(--uv-color-text,#0f172a);font-family:var(--uv-font-sans,system-ui,sans-serif);overflow:hidden}.uv-accordion__summary{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1rem 1.1rem;font-weight:700;cursor:pointer;list-style:none}.uv-accordion__summary::-webkit-details-marker{display:none}.uv-accordion__summary:focus-visible{outline:0;box-shadow:inset var(--uv-focus-ring)}.uv-accordion__chevron{transition:transform .15s}.uv-accordion[open] .uv-accordion__chevron{transform:rotate(180deg)}.uv-accordion__content{padding:0 1.1rem 1.1rem;color:var(--uv-color-text-muted,#64748b)}</style>
